    def _available(self, warehouse: str, sku: str, now: datetime) -> int:
        free = self._store.get_qty(warehouse, sku) - self._store.reserved_qty(warehouse, sku, now)
        return max(0, free)

    def _find(self, order_id: str) -> ReservationRecord:
        record = self._store.get_reservation(order_id)
